// Validate and parse LLM response for receipt items
const webhookData = $('Code – Choose Receipt Source').first().json;
const llmResponse = $input.item.json;

let items = [];

// Handle different LLM response formats
if (llmResponse.choices && llmResponse.choices[0]?.message?.content) {
  // OpenAI format
  const content = llmResponse.choices[0].message.content;
  items = JSON.parse(content);
} else if (llmResponse.content && Array.isArray(llmResponse.content)) {
  // Anthropic format
  const textContent = llmResponse.content.find(c => c.type === 'text');
  items = JSON.parse(textContent.text);
} else if (Array.isArray(llmResponse)) {
  // Direct array response
  items = llmResponse;
} else {
  throw new Error('Unexpected LLM response format');
}

if (!Array.isArray(items) || items.length === 0) {
  throw new Error('No items extracted from receipt');
}

// Validate structure
items.forEach((item, idx) => {
  if (!item.normalized_name) {
    throw new Error(`Item ${idx} missing normalized_name`);
  }
});

return [{
  json: {
    ...webhookData,
    items: items,
    items_count: items.length
  }
}];

// Merge preferences from webhook and Google Sheets
const workflowData = $('Code – Validate JSON Items').first().json;
const userRow = $input.item.json;

// Helper to parse array from string or return array
function parseArray(value, fallback = []) {
  if (Array.isArray(value)) return value;
  if (typeof value === 'string' && value.trim()) {
    try {
      return JSON.parse(value);
    } catch {
      return value.split(',').map(s => s.trim());
    }
  }
  return fallback;
}

// Webhook overrides sheet, with fallbacks
const userProfile = {
  user_id: workflowData.user_id || 'anonymous',
  plan_tier: workflowData.plan_tier || 'basic',
  household_size: workflowData.household_size || userRow.household_size || 2,
  dietary_preferences: workflowData.dietary_preferences || parseArray(userRow.dietary_preferences, ['no_restrictions']),
  cooking_skill: workflowData.cooking_skill || userRow.cooking_skill || 'beginner',
  max_prep_time_minutes: workflowData.max_prep_time_minutes || userRow.max_prep_time_minutes || 30
};

return [{
  json: {
    items: workflowData.items,
    items_count: workflowData.items_count,
    user_profile: userProfile
  }
}];

