// Validate meal plan JSON
const workflowData = $('IF – Tier Logic').first().json;
const llmResponse = $input.item.json;

let mealPlan = {};

// Handle different LLM response formats
if (llmResponse.choices && llmResponse.choices[0]?.message?.content) {
  const content = llmResponse.choices[0].message.content;
  mealPlan = JSON.parse(content);
} else if (llmResponse.content && Array.isArray(llmResponse.content)) {
  const textContent = llmResponse.content.find(c => c.type === 'text');
  mealPlan = JSON.parse(textContent.text);
} else if (llmResponse.plan_metadata) {
  mealPlan = llmResponse;
} else {
  throw new Error('Unexpected meal plan format');
}

// Validate structure
if (!mealPlan.plan_metadata || !mealPlan.days || !Array.isArray(mealPlan.days)) {
  throw new Error('Invalid meal plan structure');
}

if (mealPlan.days.length !== 7) {
  throw new Error('Meal plan must contain exactly 7 days');
}

return [{
  json: {
    user_profile: workflowData.user_profile,
    meal_plan: mealPlan
  }
}];

// Build human-readable summary
const { user_profile, meal_plan } = $input.item.json;
const meta = meal_plan.plan_metadata;

const dietaryText = meta.dietary_preferences.join(', ');
const summary = `7-day ${dietaryText} meal plan for household of ${meta.household_size}, max ${meta.max_prep_time_minutes} min prep time. Tier: ${meta.tier}. Week: ${meta.week_label}. Est. food waste reduction: ${meta.estimated_food_waste_reduction_percent}%.`;

return [{
  json: {
    user_id: user_profile.user_id,
    plan_tier: meta.tier,
    week_label: meta.week_label,
    plan_json: JSON.stringify(meal_plan),
    summary_text: summary,
    meal_plan: meal_plan,
    timestamp: new Date().toISOString()
  }
}];

// Build final API response
const data = $input.item.json;

return [{
  json: {
    status: 'success',
    user_id: data.user_id,
    plan_tier: data.plan_tier,
    summary: data.summary_text,
    plan: data.meal_plan
  }
}];

// Format error response
const error = $input.item.json.error;

const errorResponse = {
  status: 'error',
  error_type: error.name || 'UnknownError',
  message: error.message || 'An unexpected error occurred',
  timestamp: new Date().toISOString()
};

return [{ json: errorResponse }];
